 setVal("incentive",a.seller_incentive);setVal("promo",a.promotion);setVal("wallet",old.seller_wallet_address);
 ["shippingAvailable","sellerShips","buyerShips","pickupAvailable","deliveryAvailable","internationalSale"].forEach(k=>{if(old[{shippingAvailable:"shipping_available",sellerShips:"seller_arranges_shipping",buyerShips:"buyer_arranges_shipping",pickupAvailable:"pickup_available",deliveryAvailable:"delivery_available",internationalSale:"international_sale"}[k]]!==undefined)$("#"+k).checked=!!old[{shippingAvailable:"shipping_available",sellerShips:"seller_arranges_shipping",buyerShips:"buyer_arranges_shipping",pickupAvailable:"pickup_available",deliveryAvailable:"delivery_available",internationalSale:"international_sale"}[k]]});
 setVal("shippingNotes",old.shipping_notes);$("#legalAttestation").checked=!!old.seller_legal_attestation;$("#ownershipAttestation").checked=!!old.ownership_attestation;$("#prohibitedAttestation").checked=!!old.prohibited_goods_attestation;drawDetails($("#cat").value,old);syncPreview();
